-- Sample recipes, owned by the first signed-up user. Run after schema.sql (sign up once first). Safe to run more than once.
do $$ declare seed_author uuid; begin select id into seed_author from auth.users order by created_at limit 1; if seed_author is not null then
on conflict (id) do nothing;
-- Matches the built-in sample ids in lib/types.ts, so saves and ratings on samples land on real rows.
update public.recipes set is_hostel_friendly = true where id in ('00000000-0000-4000-8000-000000000002', '00000000-0000-4000-8000-000000000003');
update public.recipes set image_url = 'https://images.unsplash.com/photo-1703763253190-4af44c87a23e?auto=format&fit=crop&w=1200&q=85' where id = '00000000-0000-4000-8000-000000000004'; end if; end $$;