insert into public.recipes (id, author_id, title, category, is_veg, cooking_time, servings, image_url, ingredients, steps, description) values
('00000000-0000-4000-8000-000000000001', seed_author, 'Dilli Wali Butter Chicken', 'Non-Veg', false, 45, 4, 'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?auto=format&fit=crop&w=1200&q=85', '["500g chicken","2 tbsp butter","1 cup tomato puree","1/2 cup cream","Garam masala"]', '["Marinate chicken with spices for 30 minutes.","Sear until golden and set aside.","Cook tomato puree with butter and spices.","Fold chicken and cream into the gravy."]', 'Silky, smoky and deeply comforting.'),
('00000000-0000-4000-8000-000000000002', seed_author, 'Amritsari Chole Kulche', 'Breakfast', true, 35, 3, 'https://images.unsplash.com/photo-1626132647523-66f5bf380027?auto=format&fit=crop&w=1200&q=85', '["2 cups chickpeas","2 onions","2 tomatoes","Kulcha","Chole masala"]', '["Soak chickpeas overnight and pressure cook.","Make a spiced onion tomato masala.","Simmer chickpeas until thick.","Serve hot with toasted kulcha."]', 'The kind of Sunday breakfast that makes the whole home smell wonderful.'),
('00000000-0000-4000-8000-000000000003', seed_author, 'Palak Paneer, Dhaba Style', 'Sabzi', true, 30, 4, 'https://images.unsplash.com/photo-1588166524941-3bf61a9c41db?auto=format&fit=crop&w=1200&q=85', '["500g spinach","250g paneer","1 onion","Ginger garlic","Fresh cream"]', '["Blanch spinach and blend smooth.","Saute aromatics until golden.","Add spinach puree and season.","Fold in paneer and finish with cream."]', 'Velvety greens and pillowy paneer.'),
('00000000-0000-4000-8000-000000000004', seed_author, 'Mango Shrikhand', 'Sweets', true, 15, 4, 'https://images.unsplash.com/photo-1703763253190-4af44c87a23e?auto=format&fit=crop&w=1200&q=85', '["2 cups hung curd","1 cup mango pulp","4 tbsp powdered sugar","Cardamom","Pistachios"]', '["Whisk hung curd until creamy.","Fold in mango pulp and sugar.","Chill for two hours.","Garnish with cardamom and pistachios."]', 'A bright, cool dessert for warm afternoons.'),
('00000000-0000-4000-8000-000000000005', seed_author, 'Masala Moong Dal', 'Dal & Rice', true, 25, 4, 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=1200&q=85', '["1 cup moong dal","1 tomato","Cumin","Turmeric","Coriander"]', '["Wash and pressure cook dal.","Prepare cumin tomato tadka.","Stir tadka into dal.","Finish with coriander."]', 'A weeknight staple with a bright tempering.'),
('00000000-0000-4000-8000-000000000006', seed_author, 'Crispy Aloo Samosa', 'Snacks', true, 50, 6, 'https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=1200&q=85', '["Potatoes","Samosa wrappers","Peas","Cumin","Chaat masala"]', '["Make spiced potato filling.","Fold wrappers into cones.","Fill and seal samosas.","Fry until golden and crisp."]', 'Golden little parcels made for chai time.'),
('00000000-0000-4000-8000-000000000007', seed_author, 'Methi Paratha', 'Roti & Paratha', true, 30, 4, 'https://images.unsplash.com/photo-1617692855027-33b14f061079?auto=format&fit=crop&w=1200&q=85', '["Wheat flour","Fresh methi","Yogurt","Carom seeds","Ghee"]', '["Knead flour with methi and yogurt.","Rest the dough.","Roll and cook with ghee.","Serve with curd."]', 'Flaky, fragrant and perfect with curd.'),
('00000000-0000-4000-8000-000000000008', seed_author, 'Nimbu Pudina Shikanji', 'Drinks', true, 10, 4, 'https://images.unsplash.com/photo-1556679343-c7306c1976bc?auto=format&fit=crop&w=1200&q=85', '["Lemons","Mint","Sugar","Roasted cumin","Chilled water"]', '["Make a lemon mint syrup.","Add roasted cumin.","Top with chilled water and ice.","Serve immediately."]', 'A cooling glass of sunshine.')
